        self.val = val
        self.left = left
        self.right = right

def inorderTraversal(root: TreeNode):
    result = []

    def traverse(node):
        if not node:
            return
        traverse(node.left)
        result.append(node.val)
        traverse(node.right)

    traverse(root)
    return result

